// Builds idra-photo.mjs: the whole server in one file, so a fresh clone needs no npm install.
import { build } from 'esbuild';

const banner = [
  '// Idra Photo single-file build. Generated by `npm run bundle` from src/. Do not edit by hand.',
  "import { createRequire as __idraCreateRequire } from 'node:module';",
  'const require = __idraCreateRequire(import.meta.url);',
].join('\n');

await build({
  entryPoints: ['src/cli.ts'],
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  outfile: 'idra-photo.mjs',
  legalComments: 'eof',
  logLevel: 'warning',
  banner: { js: banner },
});
